(()=>{const input=document.querySelector('#search'),cards=[...document.querySelectorAll('.article-card')],filters=[...document.querySelectorAll('[data-filter]')];let category='全部文章';function update(){const terms=(input?.value||'').toLowerCase().trim().split(/\s+/).filter(Boolean);document.querySelector('.cards')?.classList.toggle('is-filtered',category!=='全部文章'||terms.length>0);let count=0;cards.forEach(card=>{const ok=(category==='全部文章'||card.dataset.category===category)&&terms.every(t=>card.dataset.search.toLowerCase().includes(t));card.hidden=!ok;if(ok)count++});const empty=document.querySelector('#empty');if(empty)empty.hidden=count>0;const status=document.querySelector('#results-status');if(status){status.textContent=terms.length?`“${input.value.trim()}” · 找到 ${count} 篇文章`:`找到 ${count} 篇文章`;status.hidden=!terms.length;}filters.forEach(f=>{const active=f.dataset.filter===category;f.classList.toggle('active',active);f.setAttribute('aria-pressed',String(active))})}input?.addEventListener('input',update);document.querySelector('#search-form')?.addEventListener('submit',e=>{e.preventDefault();category='全部文章';update();document.querySelector('#guides')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});});filters.forEach(f=>f.addEventListener('click',()=>{category=f.dataset.filter;update()}));document.querySelector('#reset-search')?.addEventListener('click',()=>{category='全部文章';input.value='';update();input.focus()});document.addEventListener('keydown',e=>{if(e.key==='/'&&input&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();input.focus()}});document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const original=button.innerHTML;try{await navigator.clipboard.writeText(button.dataset.copy);button.textContent='已复制 AIG';setTimeout(()=>button.innerHTML=original,1800)}catch{button.textContent='邀请码：AIG（请手动复制）'}}));if(input)update()})();

// Cache only content-hashed public assets; page HTML always uses the network.
if ('serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('/performance-cache.js', { updateViaCache: 'none' }).catch(() => {});
  }, { once: true });
}
